#include <string.h>

static jmp_buf app_loop_abort;
static sensors_snapshot_t test_snapshot;
static uint32_t fake_now_ms;
static unsigned int now_call_count;
static unsigned int sequence_number;
static unsigned int sh1106_init_order;
static unsigned int first_logo_page_order;
static unsigned int logo_enable_order;
static unsigned int logo_page_count;
static uint32_t first_logo_page_time;
static uint32_t logo_enable_time;
static unsigned int uart_accessor_calls;

/* This accessor is declared by the firmware source but has no public header. */
UART_HandleTypeDef *firmgen_uart_handle(void)
{
    uart_accessor_calls++;
    return NULL;
}

static uint32_t platform_now_callback(int cmock_num_calls)
{
    (void)cmock_num_calls;
    now_call_count++;
    /* app_start samples time for display_init and sensors_init before its loop. */
    fake_now_ms = (now_call_count <= 2U) ? 0U : 100U;
    return fake_now_ms;
}

static void stop_app_loop_callback(int cmock_num_calls)
{
    /* Allow one complete app-loop pass, then escape the intentionally endless loop. */
    if (cmock_num_calls >= 2)
    {
        longjmp(app_loop_abort, 1);
    }
}

static bool sh1106_init_callback(sh1106_send_t send, uint8_t address,
                                 int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    sh1106_init_order = ++sequence_number;
    return true;
}

static bool sh1106_page_callback(sh1106_send_t send, uint8_t address,
                                 uint8_t page, const uint8_t *pixels,
                                 int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    if ((page < 8U) &&
        (pixels == &display_logo[(uint16_t)page * 128U]))
    {
        if (logo_page_count == 0U)
        {
            first_logo_page_order = sequence_number + 1U;
            first_logo_page_time = fake_now_ms;
        }
        logo_page_count++;
    }
    sequence_number++;
    return true;
}

static bool sh1106_enable_callback(sh1106_send_t send, uint8_t address,
                                   int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)cmock_num_calls;
    logo_enable_order = ++sequence_number;
    logo_enable_time = fake_now_ms;
    return true;
}

void setUp(void)
{
    memset(&test_snapshot, 0, sizeof(test_snapshot));
    fake_now_ms = 0U;
    now_call_count = 0U;
    sequence_number = 0U;
    sh1106_init_order = 0U;
    first_logo_page_order = 0U;
    logo_enable_order = 0U;
    logo_page_count = 0U;
    first_logo_page_time = UINT32_MAX;
    logo_enable_time = UINT32_MAX;
    uart_accessor_calls = 0U;
}

void tearDown(void)
{
}

void test_IF_006_01(void)
{
    platform_io_init_ExpectAndReturn(true);
    platform_io_now_ms_StubWithCallback(platform_now_callback);
    platform_io_transmit_IgnoreAndReturn(true);
    platform_io_log_Ignore();
    platform_io_poll_Ignore();
    platform_io_led_Ignore();

    sensors_init_Ignore();
    sensors_process_Ignore();
    sensors_snapshot_IgnoreAndReturn(&test_snapshot);
    ride_events_init_Ignore();
    telemetry_process_Ignore();

    firmgen_telemetry_start_Ignore();
    firmgen_telemetry_poll_StubWithCallback(stop_app_loop_callback);

    sh1106_init_StubWithCallback(sh1106_init_callback);
    sh1106_page_StubWithCallback(sh1106_page_callback);
    sh1106_enable_StubWithCallback(sh1106_enable_callback);

    if (setjmp(app_loop_abort) == 0)
    {
        app_start();
    }

    TEST_ASSERT_TRUE(sh1106_init_order > 0U);
    TEST_ASSERT_EQUAL_UINT32(8U, logo_page_count);
    TEST_ASSERT_TRUE(first_logo_page_order > sh1106_init_order);
    TEST_ASSERT_TRUE(logo_enable_order > first_logo_page_order);
    TEST_ASSERT_TRUE(first_logo_page_time <= 100U);
    TEST_ASSERT_TRUE(logo_enable_time <= 100U);
}
